using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions; namespace JTradeERP.Application.Features.MasterData.UnitsOfMeasure.GetUnitOfMeasureById; public sealed class GetUnitOfMeasureByIdHandler(IApplicationDbContext db):IRequestHandler<GetUnitOfMeasureByIdQuery,GetUnitOfMeasureByIdResponse>{public Task<GetUnitOfMeasureByIdResponse> Handle(GetUnitOfMeasureByIdQuery r,CancellationToken ct){var e=db.UnitsOfMeasure.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Unit of Measure not found.");return Task.FromResult(new GetUnitOfMeasureByIdResponse(e.Id,e.Code,e.Name));}}
